#pragma once
// Types of the TP particle tables (sword-particles-01). sword_particles_data.h fills them; it is generated by
// scripts/gen_sword_particles.py from docs/data/tp-particles/tp-particles.json (JPA 2.10 resources of Twilight
// Princess, decoded by scripts/tp_jpa.py). Units are the JSON's: TP centimetres, TP frames (30 fps), degrees; the
// simulation (sword_particles.h) converts cm to RE4 mm (x10) and runs one tick per TP frame.
#include <cstdint>

namespace link_runtime::sword_particles {
enum class Volume:uint8_t {Point,Sphere,Cylinder,Circle};
// Billboard: a quad facing the camera. Direction: one quad along the direction (rotating about it). DirectionCross: two
// crossed quads along the direction (drawn as one camera-facing spindle, design section 2.2).
enum class Shape:uint8_t {Billboard,Direction,DirectionCross};
enum class DirType:uint8_t {Velocity,Position};           // the direction: the frame's velocity, or the position from the emitter
enum class Formula:uint8_t {EnvPrmLerp,PrmTex};           // TEV colour: env*(1-tex)+prm*tex, or prm*tex
enum class ColourAnim:uint8_t {Normal,Repeat,Reverse,Merge,Random};
enum class FieldType:uint8_t {Gravity,Spin};
constexpr int kMaxKeys=4,kMaxFields=2;
struct Key {uint16_t frame;uint32_t rgb;uint8_t a;};
// JPADynamicsBlock: the emitter volume, the initial velocity terms (cm per frame), the rate and the particle life.
struct Dynamics {
    Volume volume;float volume_cm,sweep,min_radius;uint16_t div_number;bool fixed_density,fixed_interval,inherit_scale,follow;
    float scale[3],translation_cm[3],direction[3],rotation_deg[3];
    float omni,axis,random,dir_speed,spread,ratio_random;
    float rate,rate_random;uint16_t emit_every,max_frame,start_frame;
    float life,life_random,air,moment_random;
};
// JPABaseShape: the shape, its size (the quad, cm), the blend and the colours (prm/env, optional keys per frame).
struct Look {
    Shape shape;DirType dir_type;bool anchor_bottom;float size_cm[2];bool additive;Formula formula;
    uint32_t prm,env;uint8_t prm_a,env_a;ColourAnim anim;uint16_t anm_max_frame;uint8_t loop_offset,loop_mask;
    uint8_t prm_keys,env_keys;Key prm_key[kMaxKeys],env_key[kMaxKeys];
};
// JPAExtraShape: scale and alpha curves over the normalised life, and the spin of the quad.
struct ScaleAnim {bool on,xy_differ;float in_timing,out_timing,in_x,out_x,in_y,out_y,random;};
struct AlphaAnim {bool on;float in_timing,out_timing,in_value,base,out_value;};
struct Rotate {bool on;float init_deg,random_deg,speed_deg,speed_random,direction;};
// JPAFieldBlock: gravity (an acceleration, add_type 0) or spin (rotates the position about dir, add_type 2: a push for
// this frame only). Fade and enable times are the normalised life.
struct Field {FieldType type;uint8_t add_type;bool world,enable,disable,fade_in,fade_out;float dir[3];
    float mag,en_time,dis_time,fade_in_time,fade_out_time;};
struct Def {
    const char* name;uint16_t id;const char* fingerprint;const char* texture;
    Dynamics dyn;Look look;ScaleAnim scale;AlphaAnim alpha;Rotate rotate;uint8_t fields;Field field[kMaxFields];
};
} // namespace link_runtime::sword_particles
